<?php
declare(strict_types=1);
require __DIR__.'/includes/config.php';require __DIR__.'/includes/live.php';require __DIR__.'/includes/shell.php';require __DIR__.'/includes/reptile_core.php';
$uid=ir_current_user_id();$error='';
$extended=ir_table_exists($pdo,'wp_ir2_inventory_details')&&ir_table_exists($pdo,'wp_ir2_inventory_categories');
$shoppingReady=ir_table_exists($pdo,'wp_ir2_nakupni_list');
$tab=preg_replace('/[^a-z\-]/','',(string)($_GET['tab']??'overview'));
if(!in_array($tab,['overview','items','shopping','calculator','categories'],true))$tab='overview';
function stock_number(string $key): string {$value=str_replace(',', '.',trim((string)($_POST[$key]??'0')));if(!preg_match('/^\d{1,9}(?:\.\d{1,2})?$/D',$value))throw new InvalidArgumentException('Číslo musí být nezáporné, nejvýše se dvěma desetinnými místy.');return $value;}

if($_SERVER['REQUEST_METHOD']==='POST'){
    ir_verify_csrf();$action=(string)($_POST['action']??'');$id=ir_int($_POST['id']??0);
    try{
        $pdo->beginTransaction();
        if($action==='save'){
            $name=trim((string)($_POST['nazev']??''));$category=trim((string)($_POST['kategorie']??''));
            if($name===''||mb_strlen($name)>180||$category===''||mb_strlen($category)>100)throw new InvalidArgumentException('Vyplň platný název a vlastní kategorii skladu.');
            if($id&&!ir_action_owned($pdo,'wp_ir2_sklad',$uid,$id))throw new InvalidArgumentException('Položka nebyla nalezena.');
            $expiry=(string)($_POST['expirace']??'');if($expiry!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$expiry)||date('Y-m-d',strtotime($expiry))!==$expiry))throw new InvalidArgumentException('Neplatná expirace.');
            $vals=[$name,$category,stock_number('mnozstvi'),trim((string)($_POST['jednotka']??'ks'))?:'ks',stock_number('minimum'),$expiry?:null,trim((string)($_POST['poznamka']??'')),$uid];
            if($id)$pdo->prepare('UPDATE wp_ir2_sklad SET nazev=?,kategorie=?,mnozstvi=?,jednotka=?,minimum=?,expirace=?,poznamka=? WHERE user_id=? AND id=?')->execute([...$vals,$id]);
            else{$pdo->prepare('INSERT INTO wp_ir2_sklad(nazev,kategorie,mnozstvi,jednotka,minimum,expirace,poznamka,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute($vals);$id=(int)$pdo->lastInsertId();}
            if($extended){$v=[$uid,$id];foreach(['variant','size_label','weight_class'] as $key)$v[]=mb_substr(trim((string)($_POST[$key]??'')),0,100);$v[]=stock_number('purchase_price');$v[]=stock_number('sale_price');$v[]=mb_substr(trim((string)($_POST['supplier']??'')),0,190);$v[]=($_POST['purchased_on']??'')?:null;$v[]=mb_substr(trim((string)($_POST['storage_place']??'')),0,190);$pdo->prepare('INSERT INTO wp_ir2_inventory_details(user_id,item_id,variant,size_label,weight_class,purchase_price,sale_price,supplier,purchased_on,storage_place) VALUES(?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE variant=VALUES(variant),size_label=VALUES(size_label),weight_class=VALUES(weight_class),purchase_price=VALUES(purchase_price),sale_price=VALUES(sale_price),supplier=VALUES(supplier),purchased_on=VALUES(purchased_on),storage_place=VALUES(storage_place)')->execute($v);}
        }elseif($action==='delete'){
            $q=$pdo->prepare('SELECT mnozstvi FROM wp_ir2_sklad WHERE user_id=? AND id=? FOR UPDATE');$q->execute([$uid,$id]);$qty=$q->fetchColumn();if($qty===false||(float)$qty!==0.0)throw new InvalidArgumentException('Smazat lze pouze existující položku s nulovou zásobou.');
            if($extended)$pdo->prepare('DELETE FROM wp_ir2_inventory_details WHERE user_id=? AND item_id=?')->execute([$uid,$id]);$pdo->prepare('DELETE FROM wp_ir2_sklad WHERE user_id=? AND id=?')->execute([$uid,$id]);
        }elseif($extended&&$action==='category-adopt'){
            $name=trim((string)($_POST['name']??''));if($name==='')throw new InvalidArgumentException('Chybí název kategorie.');
            $exists=(int)ir_scalar($pdo,'SELECT COUNT(*) FROM wp_ir2_inventory_categories WHERE user_id=? AND name=?',[$uid,$name],0);if(!$exists)$pdo->prepare('INSERT INTO wp_ir2_inventory_categories(user_id,name,icon,position) VALUES(?,?,?,?)')->execute([$uid,$name,'inventory',500]);
        }elseif($extended&&in_array($action,['category-save','category-delete'],true)){
            $q=$pdo->prepare('SELECT name FROM wp_ir2_inventory_categories WHERE user_id=? AND id=? FOR UPDATE');$q->execute([$uid,$id]);$old=$q->fetchColumn();if($id&&!$old)throw new InvalidArgumentException('Kategorie nebyla nalezena.');
            if($action==='category-delete'){$q=$pdo->prepare('SELECT COUNT(*) FROM wp_ir2_sklad WHERE user_id=? AND kategorie=?');$q->execute([$uid,$old]);if((int)$q->fetchColumn()>0)throw new InvalidArgumentException('Kategorie obsahuje položky. Nejdřív je přesuň nebo přejmenuj.');$pdo->prepare('DELETE FROM wp_ir2_inventory_categories WHERE user_id=? AND id=?')->execute([$uid,$id]);}
            else{$name=trim((string)($_POST['name']??''));if($name===''||mb_strlen($name)>100)throw new InvalidArgumentException('Zvol název kategorie.');$icon=in_array($_POST['icon']??'',['inventory','feeding','medicine','habitat','supplement','water','cleaning','health','reproduction'],true)?$_POST['icon']:'inventory';$position=max(0,min(999,(int)($_POST['position']??0)));$dup=(int)ir_scalar($pdo,'SELECT COUNT(*) FROM wp_ir2_inventory_categories WHERE user_id=? AND name=? AND id<>?',[$uid,$name,$id],0);if($dup)throw new InvalidArgumentException('Kategorie s tímto názvem už existuje.');if($id){$pdo->prepare('UPDATE wp_ir2_inventory_categories SET name=?,icon=?,position=? WHERE user_id=? AND id=?')->execute([$name,$icon,$position,$uid,$id]);$pdo->prepare('UPDATE wp_ir2_sklad SET kategorie=? WHERE user_id=? AND kategorie=?')->execute([$name,$uid,$old]);}else $pdo->prepare('INSERT INTO wp_ir2_inventory_categories(user_id,name,icon,position) VALUES(?,?,?,?)')->execute([$uid,$name,$icon,$position]);}
        }elseif($shoppingReady&&$action==='shopping-add'){$name=trim((string)($_POST['shopping_name']??''));if($name==='')throw new InvalidArgumentException('Zadej položku nákupního listu.');$qty=mb_substr(trim((string)($_POST['shopping_qty']??'')),0,80);$priority=in_array((string)($_POST['shopping_priority']??''),['Nízká','Normální','Vysoká'],true)?(string)$_POST['shopping_priority']:'Normální';$pdo->prepare('INSERT INTO wp_ir2_nakupni_list(user_id,nazev,mnozstvi,priorita) VALUES(?,?,?,?)')->execute([$uid,mb_substr($name,0,190),$qty?:null,$priority]);
        }elseif($shoppingReady&&$action==='shopping-toggle')$pdo->prepare('UPDATE wp_ir2_nakupni_list SET hotovo=1-hotovo,completed_at=CASE WHEN hotovo=0 THEN NOW() ELSE NULL END WHERE user_id=? AND id=?')->execute([$uid,$id]);
        elseif($shoppingReady&&$action==='shopping-delete')$pdo->prepare('DELETE FROM wp_ir2_nakupni_list WHERE user_id=? AND id=?')->execute([$uid,$id]);
        else throw new InvalidArgumentException('Neplatná akce.');
        $pdo->commit();
        $retTab=(string)($_POST['return_tab']??($action==='save'?'items':($action==='shopping-add'||str_starts_with($action,'shopping-')?'shopping':(str_starts_with($action,'category-')?'categories':$tab))));
        ir_redirect('inventory.php?tab='.rawurlencode($retTab));
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Inventory: '.$e->getMessage());$error=$e instanceof InvalidArgumentException?$e->getMessage():'Změnu se nepodařilo uložit.';}
}

$q=$pdo->prepare($extended?'SELECT s.*,d.variant,d.size_label,d.weight_class,d.purchase_price,d.sale_price,d.supplier,d.purchased_on,d.storage_place FROM wp_ir2_sklad s LEFT JOIN wp_ir2_inventory_details d ON d.user_id=s.user_id AND d.item_id=s.id WHERE s.user_id=? ORDER BY s.kategorie,s.nazev':'SELECT * FROM wp_ir2_sklad WHERE user_id=? ORDER BY kategorie,nazev');$q->execute([$uid]);$items=$q->fetchAll()?:[];
$custom=[];if($extended){$q=$pdo->prepare('SELECT * FROM wp_ir2_inventory_categories WHERE user_id=? ORDER BY position,name');$q->execute([$uid]);$custom=$q->fetchAll()?:[];}
$shopping=[];if($shoppingReady){$q=$pdo->prepare('SELECT * FROM wp_ir2_nakupni_list WHERE user_id=? ORDER BY hotovo,FIELD(priorita,\'Vysoká\',\'Normální\',\'Nízká\'),created_at DESC');$q->execute([$uid]);$shopping=$q->fetchAll()?:[];}
$categories=array_values(array_unique(array_filter(array_merge(array_column($custom,'name'),array_column($items,'kategorie')))));sort($categories,SORT_NATURAL|SORT_FLAG_CASE);
$category=(string)($_GET['category']??'');$view=(string)($_GET['view']??'');$search=trim((string)($_GET['q']??''));$edit=null;foreach($items as $i)if((int)$i['id']===(int)($_GET['edit']??0))$edit=$i;
$filtered=array_values(array_filter($items,fn($i)=>($category===''||$i['kategorie']===$category)&&($view!=='low'||(float)$i['mnozstvi']<=(float)$i['minimum'])&&($search===''||mb_stripos($i['nazev'].' '.($i['variant']??''),$search)!==false)));
$low=array_values(array_filter($items,fn($i)=>(float)$i['mnozstvi']<=(float)$i['minimum']));$expiring=array_values(array_filter($items,fn($i)=>!empty($i['expirace'])&&strtotime((string)$i['expirace'])<=strtotime('+30 days')));
$stockValue=0.0;foreach($items as $i)$stockValue+=(float)$i['mnozstvi']*(float)($i['purchase_price']??0);
$customMap=[];foreach($custom as $c)$customMap[(string)$c['name']]=$c;
$iconFor=function(string $cat)use($customMap):string{if(isset($customMap[$cat]))return (string)$customMap[$cat]['icon'];$l=mb_strtolower($cat,'UTF-8');if(str_contains($l,'krm')||str_contains($l,'myš')||str_contains($l,'hmyz'))return 'feeding';if(str_contains($l,'vit')||str_contains($l,'supl'))return 'supplement';if(str_contains($l,'veter')||str_contains($l,'léč'))return 'medicine';if(str_contains($l,'substr')||str_contains($l,'vybav')||str_contains($l,'technik'))return 'habitat';return 'inventory';};

ir_page_start('Sklad','inventory');if($error)echo '<p class="flash danger" role="alert">'.ir_e($error).'</p>';
?>
