 <a class="<?=$tab==='categories'?'is-active':''?>" href="inventory.php?tab=categories">Kategorie</a>
</nav>

<section class="metric-grid inventory-metrics">
 <article class="mini-metric glow-panel"><span><?=ir_visual_icon('inventory')?></span><div><small>Položky</small><strong><?=count($items)?></strong><em>celkem</em></div></article>
 <article class="mini-metric glow-panel"><span><?=ir_visual_icon('warning')?></span><div><small>Nízké zásoby</small><strong><?=count($low)?></strong><em>k dokoupení</em></div></article>
 <article class="mini-metric glow-panel"><span><?=ir_visual_icon('calendar')?></span><div><small>Expirace do 30 dní</small><strong><?=count($expiring)?></strong><em>zkontrolovat</em></div></article>
 <article class="mini-metric glow-panel"><span><?=ir_visual_icon('finance')?></span><div><small>Hodnota zásob</small><strong><?=number_format($stockValue,0,',',' ')?> Kč</strong><em>pořizovací ceny</em></div></article>
</section>

