  <div class="inventory-category-grid inventory-category-grid--custom">
   <?php foreach($categories as $cat):$catItems=array_values(array_filter($items,fn($i)=>$i['kategorie']===$cat));$lowCount=count(array_filter($catItems,fn($i)=>(float)$i['mnozstvi']<=(float)$i['minimum']));?>
   <a class="inventory-block" href="inventory.php?tab=items&category=<?=rawurlencode($cat)?>"><span class="inventory-block-icon"><?=ir_visual_icon($iconFor($cat))?></span><span><strong><?=ir_e($cat)?></strong><small><?=count($catItems)?> položek<?=$lowCount?' · '.$lowCount.' pod minimem':''?></small></span><b>›</b></a>
   <?php endforeach;?>
   <?php if(!$categories):?><a class="inventory-create-first" href="inventory.php?tab=categories"><?=ir_visual_icon('add')?><strong>Vytvořit první kategorii</strong><small>Mražené krmivo, živý hmyz, substráty, technika… názvy jsou jen na tobě.</small></a><?php endif;?>
  </div>
