 <aside class="panel glow-panel inventory-attention-panel"><header class="panel-head"><div><?=ir_visual_icon('warning')?><strong>Vyžaduje pozornost</strong></div><a href="inventory.php?tab=items&view=low">Vše →</a></header><div class="inventory-attention-list"><?php foreach(array_slice($low,0,7) as $i):?><a href="inventory.php?tab=items&edit=<?=$i['id']?>"><span><?=ir_visual_icon($iconFor((string)$i['kategorie']))?></span><div><strong><?=ir_e((string)$i['nazev'])?></strong><small><?=ir_e((string)$i['kategorie'])?></small></div><b><?=ir_e((string)$i['mnozstvi'].' '.(string)$i['jednotka'])?></b></a><?php endforeach;if(!$low):?><div class="empty-state small">Zásoby jsou nad nastavenými minimy.</div><?php endif;?></div></aside>
</section>
