ber" step=".01" min="0" name="<?=$key?>" value="<?=ir_e((string)($edit[$key]??0))?>"></label><?php endforeach?><label>Datum nákupu<input type="date" name="purchased_on" value="<?=ir_e($edit['purchased_on']??'')?>"></label></div></details><?php endif?></form><?php endif;?>
